<template><view class="page"><text class="title">通知设置</text><text class="sub">选择需要接收的家庭照护提醒</text><view class="card"><view v-for="item in items" :key="item.key" class="row"><view><text class="name">{{item.name}}</text><text class="desc">{{item.desc}}</text></view><switch :checked="item.enabled" color="#326a53" @change="e=>item.enabled=e.detail.value"/></view></view><button class="save" @tap="save">保存设置</button></view></template><script>export default{data(){return{items:[{key:'sos',name:'紧急求助',desc:'老人触发SOS时立即通知',enabled:true},{key:'medicine',name:'用药提醒',desc:'未按时确认用药时通知',enabled:true},{key:'health',name:'健康异常',desc:'关键指标异常时通知',enabled:true},{key:'activity',name:'活动变化',desc:'作息或活动明显变化时通知',enabled:false},{key:'service',name:'服务订单',desc:'上门服务状态变化提醒',enabled:true}]}},methods:{save(){uni.setStorageSync('notify_settings',this.items);uni.showToast({title:'已保存',icon:'success'})}}}</script><style scoped>.page{min-height:100vh;padding:30rpx;background:#f6f7f3}.title{display:block;font-size:40rpx;font-weight:900;color:#2d4338}.sub{display:block;margin:10rpx 0 28rpx;color:#7b857f}.card{padding:0 24rpx;background:#fff;border-radius:28rpx}.row{min-height:116rpx;display:flex;align-items:center;justify-content:space-between;border-bottom:1rpx solid #edf0ec}.row:last-child{border-bottom:none}.name,.desc{display:block}.name{font-size:25rpx;font-weight:800}.desc{margin-top:6rpx;color:#858e88;font-size:19rpx}.save{margin-top:26rpx;background:#326a53;color:#fff;border-radius:20rpx}</style>